// ─── File: DelegationDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.deleg;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DelegationDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        LoaderReport report = new LoaderReport();

        // Load the SAME class name through TWO isolating loaders that each
        // define their own copy (breaking delegation for this class).
        IsolatingLoader loaderA = new IsolatingLoader("com.bank.deleg.Ledger");
        IsolatingLoader loaderB = new IsolatingLoader("com.bank.deleg.Ledger");

        Class<?> ledgerA = loaderA.loadClass("com.bank.deleg.Ledger");
        Class<?> ledgerB = loaderB.loadClass("com.bank.deleg.Ledger");

        report.compare(ledgerA, ledgerB); // different Class objects → different types

        Object instanceA = ledgerA.getDeclaredConstructor().newInstance();
        try {
            // Attempt to treat A's instance as B's type → ClassCastException.
            ledgerB.cast(instanceA);
            log.severe(() -> "Unexpected: cast succeeded");
        } catch (ClassCastException e) {
            log.severe(() -> "ClassCastException reproduced: " + e.getMessage()
                    + "  (same name, two loaders = two types)");
        }

        // Correct path: load through the shared application loader → one type.
        Class<?> shared1 = Class.forName("com.bank.deleg.Ledger");
        Class<?> shared2 = Class.forName("com.bank.deleg.Ledger");
        log.info(() -> "Shared loader gives one type? " + (shared1 == shared2));
    }
}

// ─── Would be in IsolatingLoader.java ───
// A custom loader that, for ONE target class, loads it itself instead of
// delegating to the parent — deliberately creating a separate type.
class IsolatingLoader extends ClassLoader {
    private final String target;

    IsolatingLoader(String target) {
        super(DelegationDemo.class.getClassLoader());
        this.target = target;
    }

    @Override
    public Class<?> loadClass(String name) throws ClassNotFoundException {
        if (!name.equals(target)) {
            return super.loadClass(name); // normal delegation for everything else
        }
        // Break delegation only for the target: read bytes and define locally.
        String path = name.replace('.', '/') + ".class";
        try (var in = getParent().getResourceAsStream(path)) {
            if (in == null) return super.loadClass(name);
            byte[] bytes = in.readAllBytes();
            return defineClass(name, bytes, 0, bytes.length); // our OWN copy
        } catch (Exception e) {
            throw new ClassNotFoundException(name, e);
        }
    }
}

// ─── Would be in LoaderReport.java ───
class LoaderReport {
    private static final Logger log = Logger.getLogger("BankLog");

    void compare(Class<?> a, Class<?> b) {
        log.info(() -> "A loaded by: " + a.getClassLoader());
        log.info(() -> "B loaded by: " + b.getClassLoader());
        log.info(() -> "Same Class object? " + (a == b)); // false → trouble
    }
}

// ─── Would be in Ledger.java (the class defined twice) ───
class Ledger {
    // A simple ledger used to demonstrate type identity across loaders.
    public Ledger() { }
    @Override public String toString() { return "Ledger for National Bank of India"; }
}
